use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use std::path::PathBuf;
use std::fs;

/// Serves static documentation files from the /docs directory
/// Supports nested paths for organized documentation structure
async fn serve_docs(req: HttpRequest) -> HttpResponse {
    let path: String = req.match_info().query("filename").to_string();

    // Basic sanitization - remove null bytes
    let sanitized = path.replace('\0', "");

    // Construct the file path relative to docs root
    let base_dir = std::env::var("DOCS_ROOT").unwrap_or_else(|_| "/app/docs".to_string());
    let file_path = PathBuf::from(&base_dir).join(&sanitized);

    // Attempt to read and serve the file
    match fs::read_to_string(&file_path) {
        Ok(contents) => {
            let content_type = if sanitized.ends_with(".md") {
                "text/markdown"
            } else if sanitized.ends_with(".html") {
                "text/html"
            } else {
                "text/plain"
            };
            HttpResponse::Ok()
                .content_type(content_type)
                .body(contents)
        }
        Err(e) => {
            log::warn!("Failed to read file {:?}: {}", file_path, e);
            HttpResponse::NotFound().body("Document not found")
        }
    }
}

/// Health check endpoint
async fn health() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

/// List available documentation files (non-recursive)
async fn list_docs() -> HttpResponse {
    let base_dir = std::env::var("DOCS_ROOT").unwrap_or_else(|_| "/app/docs".to_string());
    match fs::read_dir(&base_dir) {
        Ok(entries) => {
            let files: Vec<String> = entries
                .filter_map(|e| e.ok())
                .filter(|e| e.path().is_file())
                .filter_map(|e| e.file_name().into_string().ok())
                .collect();
            HttpResponse::Ok().json(files)
        }
        Err(_) => HttpResponse::InternalServerError().body("Cannot list documents")
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    let bind_addr = std::env::var("BIND_ADDR").unwrap_or_else(|_| "0.0.0.0:8080".to_string());
    log::info!("Starting documentation server on {}", bind_addr);

    HttpServer::new(|| {
        App::new()
            .route("/health", web::get().to(health))
            .route("/docs", web::get().to(list_docs))
            .route("/docs/{filename:.*}", web::get().to(serve_docs))
    })
    .bind(&bind_addr)?
    .run()
    .await
}
